// Cada modelo con distintos niveles de razonamiento (reasoning_effort). Gasta una fracción de centavo.
const modelos = ['glm-5p3-flash', 'glm-5p3', 'kimi-k3p1-pro', 'qwen3p8-max'];
const niveles = ['none', 'low'];
const items = [];
for (const corto of modelos) for (const nivel of niveles) items.push({ json: { corto: `${corto} [${nivel}]`, modelo: `accounts/fireworks/models/${corto}`, nivel } });
return items;

// Resumen sin mostrar nada sensible: modelo, estado HTTP y, si falla, el mensaje de error.
return $input.all().map((item, i) => {
  const modelo = $('Modelos a probar').all()[i].json.corto;
  const estado = item.json.statusCode;
  const cuerpo = item.json.body || {};
  const respuesta = cuerpo.choices?.[0]?.message?.content;
  return { json: {
    modelo,
    estado,
    funciona: estado === 200,
    respuesta: typeof respuesta === 'string' ? respuesta.slice(0, 60) : null,
    tokens: cuerpo.usage ?? null,
    error: estado === 200 ? null : (cuerpo.error?.message ?? JSON.stringify(cuerpo).slice(0, 200)),
  } };
});
